function openPause(){if(!G.battle||G.battle.ending)return;showModal('pause',modalHeader('Battle paused','The battle and escape clock are stopped.')+`<div class="button-row"><button class="solid-btn" id="resume-battle">Resume</button><button class="solid-btn" id="pause-options">Options</button><button class="solid-btn" id="pause-help">Controls</button><button class="solid-btn" id="pause-title">Return to title</button></div><p class="lead" style="margin-top:20px">Return to title loads from your last field checkpoint next time.</p>`);bindClose();$('#resume-battle').onclick=()=>{hideModal();Sound.sfx('ok')};$('#pause-options').onclick=openOptions;$('#pause-help').onclick=openHelp;$('#pause-title').onclick=toTitle;$('#resume-battle').focus()}
