/* Colours are written exactly as the old shader wrote them: no colour
   management, no sRGB output conversion, raw atlas texels. */
THREE.ColorManagement.enabled=false;
kit.renderer.outputColorSpace=THREE.LinearSRGBColorSpace;
const scene=new THREE.Scene();
scene.background=new THREE.Color(.028,.065,.057);
const camera=new THREE.OrthographicCamera(-1,1,1,-1,.1,120);
const camState={size:13.3,at:new THREE.Vector3()};
const VPm=new THREE.Matrix4(),_proj=new THREE.Matrix4();
const uLight=TSL.uniform(new THREE.Vector3(0,5,-7)),uAlarm=TSL.uniform(0),uSim=TSL.uniform(0);

/* One node material for the whole world, a port of the original shader:
   per-vertex flat light (0.39 ambient + 0.58 key from (-.5, 1, .5)), a per-mesh
   brightness boost, the green glow around the room's light, emissive tints,
   the haze beyond 16 m, the red alarm wash, screen noise and 42-step colour.
   The combat simulator adds a holographic grid on the same material. */
function createWorldMaterial(atlas){
  const {Fn,uniform,attribute,varying,texture,uv,vec2,vec3,vec4,float,positionLocal,normalLocal,modelWorldMatrix,normalize,dot,length,clamp,mix,fract,sin,floor,step,screenCoordinate}=TSL;
  const boost=uniform(0).onObjectUpdate(({object})=>object.userData.boost||0);
  const tint=attribute('tint','vec3'),emit=attribute('emit','float');
  const world=modelWorldMatrix.mul(vec4(positionLocal,1)).xyz;
  const normal=normalize(modelWorldMatrix.mul(vec4(normalLocal,0)).xyz);
  const shade=float(.39).add(dot(normal,normalize(vec3(-.5,1,.5))).max(0).mul(.58));
  const glow=float(1).sub(length(world.sub(uLight)).div(13)).max(0);
  const vColor=varying(tint.mul(shade.add(boost)).add(vec3(.08,.25,.16).mul(glow)).add(tint.mul(emit)));
  const vWorld=varying(world);
  const m=new THREE.MeshBasicNodeMaterial({side:THREE.DoubleSide});
  m.fog=false;
  m.name='world';
  m.colorNode=Fn(()=>{
    const col=texture(atlas,uv()).rgb.mul(vColor).toVar();
    col.assign(mix(col,vec3(.025,.075,.052),clamp(length(vWorld.xz).sub(16).mul(.018),0,.65)));
    col.addAssign(vec3(.1,.013,0).mul(uAlarm));
    const grid=step(.93,fract(vWorld.x.mul(.5))).max(step(.93,fract(vWorld.z.mul(.5))));
    const holo=vec3(dot(col,vec3(.3,.59,.11))).mul(vec3(.5,1.05,.95)).add(vec3(.08,.32,.3).mul(grid));
    col.assign(mix(col,holo,uSim.mul(.8)));
    const n=fract(sin(dot(screenCoordinate.xy,vec2(12.9898,78.233))).mul(43758.5453));
    col.addAssign(n.sub(.5).mul(.027));
    col.assign(floor(col.mul(42).add(.5)).div(42));
    return vec4(col,1);
  })();
  return m;
}
const atlasTex=new THREE.CanvasTexture(textureAtlas());
