const SIDES=[-1,1],ROTOR_Y=[1.8,6.9,10.8],GLOW_Y=[1,6,10],FIELD_GUARDS=[[1,-2.3],[3.6,-3.2]],SHADOW={warden:3.3,sweeper:2.6,hound:1.4},NO_OBJS=[];
