function setCamera(ex,ey,ez,ax,ay,az,size){const aspect=kit.size.width/Math.max(1,kit.size.height);camera.left=-size*aspect/2;camera.right=size*aspect/2;camera.top=size/2;camera.bottom=-size/2;camera.position.set(ex,ey,ez);camera.lookAt(ax,ay,az);camera.updateProjectionMatrix();camera.updateMatrixWorld();_proj.makeOrthographic(camera.left,camera.right,camera.top,camera.bottom,camera.near,camera.far);VPm.multiplyMatrices(_proj,camera.matrixWorldInverse);camState.size=size;camState.at.set(ax,ay,az)}
